/*
 * @file  init_clock.c
 * @brief Mikroe clock initialization for Nordic Semiconductor NRF53 MCUs.
 *        Generated by scripts/nordic_mcus.py - do not edit, change the generator instead.
 *
 * SystemInit:
 *   1. Nordic MDK SystemInit (system_nrf5340_application.c, unmodified): errata workarounds and trims.
 *   2. Clock setup from the NECTO clock configuration (VALUE_* macros in core_header.h),
 *      in this order:
 *        a) HCLK divider (CLOCK_HFCLKCTRL: 128 or 64 MHz) written first, as the MDK does
 *        b) HFCLKSRC written and the HFXO started when CLOCK_TASKS_HFCLKSTART is set
 *        c) LFXO pins P0.00/P0.01 handed to the oscillator when LFXO is selected
 *        d) LFCLKSRC written and LFCLK started when CLOCK_TASKS_LFCLKSTART is set
 */

#include "core_header.h"
#include "mcu.h"

/* The MDK SystemInit is compiled here under another name and called from the MikroE SystemInit below. */
#define SystemInit nordic_mdk_system_init
#include "system_nrf5340_application.c"
#undef SystemInit

void SystemInit( void )
{
    nordic_mdk_system_init();

    /* Application core clock: HFCLK128M divided by 1 (128 MHz) or 2 (64 MHz). */
    NRF_CLOCK_S->HFCLKCTRL = VALUE_CLOCK_HFCLKCTRL;

    /* HFCLK128M/HFCLK64M reference: HFINT or HFXO. */
    NRF_CLOCK_S->HFCLKSRC = VALUE_CLOCK_HFCLKSRC;
    if ( VALUE_CLOCK_TASKS_HFCLKSTART & 1 ) {
        /* Start the high frequency crystal oscillator and wait until it runs. */
        NRF_CLOCK_S->EVENTS_HFCLKSTARTED = 0;
        NRF_CLOCK_S->TASKS_HFCLKSTART = 1;
        while ( 0 == NRF_CLOCK_S->EVENTS_HFCLKSTARTED );
        NRF_CLOCK_S->EVENTS_HFCLKSTARTED = 0;
    }

    /* LFXO uses XL1/XL2 on P0.00/P0.01: give both pins to the oscillator (MCUSEL = Peripheral). */
    if ( ( VALUE_CLOCK_TASKS_LFCLKSTART & 1 ) &&
         ( ( VALUE_CLOCK_LFCLKSRC & CLOCK_LFCLKSRC_SRC_Msk ) == CLOCK_LFCLKSRC_SRC_LFXO ) ) {
        NRF_P0_S->PIN_CNF[ 0 ] = GPIO_PIN_CNF_MCUSEL_Peripheral << GPIO_PIN_CNF_MCUSEL_Pos;
        NRF_P0_S->PIN_CNF[ 1 ] = GPIO_PIN_CNF_MCUSEL_Peripheral << GPIO_PIN_CNF_MCUSEL_Pos;
    }

    /* Select the LFCLK source, start LFCLK and wait until it runs. */
    if ( VALUE_CLOCK_TASKS_LFCLKSTART & 1 ) {
        NRF_CLOCK_S->LFCLKSRC = VALUE_CLOCK_LFCLKSRC;
        NRF_CLOCK_S->EVENTS_LFCLKSTARTED = 0;
        NRF_CLOCK_S->TASKS_LFCLKSTART = 1;
        while ( 0 == NRF_CLOCK_S->EVENTS_LFCLKSTARTED );
        NRF_CLOCK_S->EVENTS_LFCLKSTARTED = 0;
    }

    SystemCoreClockUpdate();
}
